<script>
 import { onMount } from 'svelte';
 import { Leaf, LayoutDashboard, CalendarDays, Users, HeartHandshake, Wallet, Settings, Plus, Search, ArrowUpRight, Clock, Check, X, Menu, ChevronRight, Bell } from 'lucide-svelte';
 let page='Ringkasan', search='', modal=false, mobile=false, notice='';
 let customer='', phone='', service='Refleksi Kaki', therapist='Ahmad Fauzi', time='14:00', date='2026-11-04';
 const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
 let services=[{name:'Refleksi Kaki',duration:60,price:150000,desc:'Waktu tenang untuk kaki yang aktif.'},{name:'Refleksi Seluruh Tubuh',duration:90,price:200000,desc:'Relaksasi menyeluruh setelah hari yang panjang.'},{name:'Refleksi & Relaksasi',duration:120,price:250000,desc:'Sesi lebih panjang, istirahat lebih nyaman.'}];
 let bookings=[{id:1,name:'Budi Santoso',phone:'081234567890',service:'Refleksi Kaki',therapist:'Ahmad Fauzi',time:'09:00',date:'2026-11-04',status:'Selesai',price:150000},{id:2,name:'Siti Rahma',phone:'081298765432',service:'Refleksi Seluruh Tubuh',therapist:'Dewi Lestari',time:'10:30',date:'2026-11-04',status:'Berlangsung',price:200000},{id:3,name:'Hendra Wijaya',phone:'081211223344',service:'Refleksi Kaki',therapist:'Ahmad Fauzi',time:'13:00',date:'2026-11-04',status:'Dikonfirmasi',price:150000},{id:4,name:'Nur Aisyah',phone:'081233445566',service:'Refleksi & Relaksasi',therapist:'Dewi Lestari',time:'15:00',date:'2026-11-04',status:'Menunggu',price:250000}];
 const team=[{name:'Ahmad Fauzi',initials:'AF',role:'Refleksi kaki & tubuh',color:'sage'},{name:'Dewi Lestari',initials:'DL',role:'Refleksi & relaksasi',color:'rose'},{name:'Rizky Pratama',initials:'RP',role:'Refleksi kaki & tubuh',color:'sand'}];
 onMount(()=>{loadServices();try{const saved=localStorage.getItem('rsk-refleksi-v1');if(saved)bookings=JSON.parse(saved);}catch{notice='Data lokal tidak dapat dimuat.';}});
 async function loadServices(){try{const response=await fetch('https://tpdcetrvlpemqcibokmb.supabase.co/rest/v1/services?select=name,duration_minutes,price,description&order=price',{headers:{apikey:'sb_publishable_vaEB2T16GjpPv51V3VYLqw_9E-5OycM'}});if(!response.ok)throw Error();const rows=await response.json();if(rows.length)services=rows.map(s=>({name:s.name,duration:s.duration_minutes,price:s.price,desc:s.description}));}catch{notice='Katalog online belum tersedia. Harga contoh digunakan.';}}
 function persist(){try{localStorage.setItem('rsk-refleksi-v1',JSON.stringify(bookings));}catch{notice='Browser tidak mengizinkan penyimpanan lokal.';}}
 function save(){const chosen=services.find(s=>s.name===service);bookings=[...bookings,{id:Date.now(),name:customer.trim(),phone,service,therapist,time,date,status:'Menunggu',price:chosen.price}];persist();modal=false;customer='';phone='';notice='Reservasi contoh berhasil ditambahkan.';}
 function finish(id){bookings=bookings.map(b=>b.id===id?{...b,status:'Selesai'}:b);persist();notice='Sesi ditandai selesai.';}
 $: filtered=bookings.filter(b=>(b.name+' '+b.service+' '+b.phone).toLowerCase().includes(search.toLowerCase()));
 $: paid=bookings.filter(b=>b.status==='Selesai').reduce((sum,b)=>sum+b.price,0);
</script>

<svelte:head><title>Rumah Sehat Kakang — Refleksi</title><meta name="description" content="Kelola reservasi, pelanggan, dan layanan refleksi Rumah Sehat Kakang."/></svelte:head>

<div class="app">
 <aside class:open={mobile}>
  <a class="brand" href="/" aria-label="Rumah Sehat Kakang"><span class="brand-icon"><Leaf size={26}/></span><span>rumah sehat<strong>kakang<span>.</span></strong></span></a>
  <div class="workspace"><span class="workspace-logo">RK</span><div>Refleksi & Relaksasi<small>Ruang kelola usaha</small></div><ChevronRight size={15}/></div>
  <p class="navlabel">MENU UTAMA</p>
  <nav>{#each [{name:'Ringkasan',icon:LayoutDashboard},{name:'Reservasi',icon:CalendarDays},{name:'Pelanggan',icon:Users},{name:'Terapis',icon:HeartHandshake},{name:'Layanan',icon:Leaf},{name:'Pembayaran',icon:Wallet}] as item}<button class:active={page===item.name} onclick={()=>{page=item.name;mobile=false;search='';}}><item.icon size={19}/>{item.name}{#if item.name==='Reservasi'}<span class="count">{bookings.length}</span>{/if}</button>{/each}</nav>
  <div class="aside-bottom"><div class="care"><Leaf size={23}/><h3>Sehat dimulai dari jeda.</h3><p>Merawat Sebelum Sakit,<br/>Ikhtiar Supaya Sehat.</p></div><button class="settings" onclick={()=>{page='Pengaturan';mobile=false;}}><Settings size={18}/>Pengaturan</button><div class="profile"><span class="avatar">KA</span><div>Kakang<small>Pemilik usaha</small></div><span class="online"></span></div></div>
 </aside>
 <main><header><div class="breadcrumb"><button class="mobile-menu" onclick={()=>mobile=!mobile} aria-label="Buka menu"><Menu size={22}/></button>Workspace <ChevronRight size={13}/><b>{page}</b></div><div class="header-right"><span class="demo">Mode demo</span><button class="bell" onclick={()=>notice='Tidak ada notifikasi baru.'} aria-label="Notifikasi"><Bell size={19}/></button><span class="avatar small">KA</span></div></header>
 <div class="content"><div class="heading"><div><p class="eyebrow">RUMAH SEHAT KAKANG</p><h1>{page==='Ringkasan'?'Selamat datang, Kakang':page}<span class="gold">{page==='Ringkasan'?'.':''}</span></h1><p class="subtitle">{page==='Ringkasan'?'Sedikit jeda, banyak kebaikan. Ini aktivitas ruang refleksi lo hari ini.':'Kelola '+page.toLowerCase()+' dalam satu tempat.'}</p></div><button class="primary" onclick={()=>modal=true}><Plus size={18}/>Reservasi baru</button></div>
 {#if notice}<div class="notice" role="status">{notice}<button onclick={()=>notice=''} aria-label="Tutup pemberitahuan"><X size={16}/></button></div>{/if}
 {#if page==='Ringkasan'}
 <section class="welcome"><div><span class="pill"><span></span>RUANG UNTUK KEMBALI NYAMAN</span><h2>Hari yang baik untuk<br/>merawat diri.</h2><p>Setiap sesi adalah kesempatan untuk menghadirkan<br class="desktop"/> rasa nyaman dan pengalaman yang berarti.</p><button onclick={()=>page='Reservasi'}>Lihat jadwal reservasi <ArrowUpRight size={17}/></button></div><div class="zen" aria-hidden="true"><div class="orb"></div><Leaf class="zen-leaf" size={130} strokeWidth={0.7}/><div class="stone s1"></div><div class="stone s2"></div><div class="stone s3"></div><span>REST. RESET. RECONNECT.</span></div></section>
 <div class="stats"><article><div><span>Total reservasi</span><CalendarDays size={18}/></div><strong>{bookings.length}<small>sesi</small></strong><p>Seluruh reservasi contoh</p></article><article><div><span>Sedang berlangsung</span><Clock size={18}/></div><strong>{bookings.filter(b=>b.status==='Berlangsung').length}<small>sesi</small></strong><p>Waktu untuk relaksasi</p></article><article><div><span>Sesi selesai</span><Check size={18}/></div><strong>{bookings.filter(b=>b.status==='Selesai').length}<small>sesi</small></strong><p>Pelayanan telah selesai</p></article><article class="revenue"><div><span>Nilai sesi selesai</span><Wallet size={18}/></div><strong>{money(paid)}</strong><p>Simulasi · belum transaksi nyata</p></article></div>
 {/if}
 {#if page==='Ringkasan'||page==='Reservasi'}<div class="columns"><section class="panel schedule"><div class="panel-heading"><div><h2>{page==='Ringkasan'?'Jadwal reservasi':'Semua reservasi'}</h2><p>Data contoh · 4 November 2026</p></div><button class="textbutton" onclick={()=>{page=page==='Ringkasan'?'Reservasi':'Ringkasan';}}> {page==='Ringkasan'?'Lihat semua':'Ringkasan'} <ChevronRight size={15}/></button></div><div class="search"><Search size={17}/><input bind:value={search} placeholder="Cari nama pelanggan atau layanan…" aria-label="Cari reservasi"/></div><div class="table-wrap"><table><thead><tr><th>PELANGGAN</th><th>JADWAL</th><th>STATUS</th><th></th></tr></thead><tbody>{#each filtered as b}<tr><td><div class="customer"><span class="initial">{b.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</span><div><strong>{b.name}</strong><small>{b.service}</small></div></div></td><td><strong>{b.time}<span class="wib"> WIB</span></strong><small>{b.date} · {b.therapist.split(' ')[0]}</small></td><td><span class="status" class:done={b.status==='Selesai'} class:ongoing={b.status==='Berlangsung'} class:waiting={b.status==='Menunggu'}>{b.status}</span></td><td>{#if b.status!=='Selesai'}<button class="finish" onclick={()=>finish(b.id)} aria-label={'Selesaikan sesi '+b.name}><Check size={16}/></button>{/if}</td></tr>{:else}<tr><td colspan="4" class="empty">Belum ada reservasi yang cocok.</td></tr>{/each}</tbody></table></div><div class="table-footer"><span>{filtered.length} reservasi ditampilkan</span><span>Semua waktu dalam WIB</span></div></section>
 {#if page==='Ringkasan'}<section class="panel therapists"><div class="panel-heading"><div><h2>Tim terapis</h2><p>Hadir dengan sepenuh hati</p></div><span class="round-icon"><HeartHandshake size={19}/></span></div>{#each team as t}<div class="therapist"><span class={'portrait '+t.color}>{t.initials}</span><div><strong>{t.name}</strong><small>{t.role}</small><span class="available">● Jadwal contoh tersedia</span></div></div>{/each}<button class="outline" onclick={()=>page='Terapis'}>Lihat semua terapis <ArrowUpRight size={16}/></button></section>{/if}</div>{/if}
 {#if page==='Layanan'}<div class="service-grid">{#each services as s,i}<section class="panel service-card"><span class="service-number">0{i+1}</span><Leaf size={36}/><h2>{s.name}</h2><p>{s.desc}</p><div><Clock size={16}/>{s.duration} menit</div><strong>{money(s.price)}</strong><button class="primary" onclick={()=>{service=s.name;modal=true;}}>Pilih layanan <Plus size={16}/></button></section>{/each}</div>{/if}
 {#if page==='Terapis'}<div class="service-grid">{#each team as t}<section class="panel service-card"><span class={'portrait large '+t.color}>{t.initials}</span><h2>{t.name}</h2><p>{t.role}</p><span class="available">● Aktif · data contoh</span><button class="outline" onclick={()=>{therapist=t.name;modal=true;}}>Jadwalkan sesi</button></section>{/each}</div>{/if}
 {#if page==='Pelanggan'}<section class="panel"><div class="panel-heading"><div><h2>Daftar pelanggan</h2><p>Diambil dari reservasi contoh</p></div></div><div class="search"><Search size={18}/><input bind:value={search} placeholder="Cari pelanggan…" aria-label="Cari pelanggan"/></div><div class="table-wrap"><table><thead><tr><th>NAMA</th><th>WHATSAPP</th><th>LAYANAN</th></tr></thead><tbody>{#each filtered.filter((b,i,a)=>a.findIndex(x=>x.phone===b.phone)===i) as b}<tr><td><strong>{b.name}</strong></td><td>{b.phone}</td><td>{b.service}</td></tr>{/each}</tbody></table></div></section>{/if}
 {#if page==='Pembayaran'}<section class="panel"><div class="panel-heading"><div><h2>Simulasi pembayaran</h2><p>Nilai sesi selesai belum berarti pembayaran telah diterima.</p></div></div><div class="table-wrap"><table><thead><tr><th>PELANGGAN</th><th>LAYANAN</th><th>NILAI SESI</th><th>STATUS SESI</th></tr></thead><tbody>{#each bookings as b}<tr><td><strong>{b.name}</strong></td><td>{b.service}</td><td>{money(b.price)}</td><td>{b.status}</td></tr>{/each}</tbody></table></div></section>{/if}
 {#if page==='Pengaturan'}<section class="panel service-card"><h2>Rumah Sehat Kakang</h2><p>Zona waktu: Asia/Jakarta (WIB)</p><p>Versi awal tampilan · data contoh disimpan di perangkat ini.</p><p>Login, pembayaran nyata, dan sinkronisasi database belum diaktifkan.</p></section>{/if}
 <footer><span>© 2026 Rumah Sehat Kakang</span><span>Merawat Sebelum Sakit, Ikhtiar Supaya Sehat <Leaf size={13}/></span></footer>
 </div></main>
</div>
{#if modal}<div class="overlay" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="panel-heading"><div><p class="eyebrow">MULAI DARI SEBUAH JEDA</p><h2 id="modal-title">Reservasi baru</h2></div><button onclick={()=>modal=false} aria-label="Tutup formulir"><X size={22}/></button></div><p class="form-note">Simulasi reservasi · tersimpan di browser perangkat ini.</p><form onsubmit={e=>{e.preventDefault();save();}}><label>Nama pelanggan<input required maxlength="80" bind:value={customer} placeholder="Nama lengkap"/></label><label>Nomor WhatsApp<input required type="tel" pattern="[0-9+ ()-]{8,20}" bind:value={phone} placeholder="08…"/></label><label>Layanan<select bind:value={service}>{#each services as s}<option>{s.name}</option>{/each}</select></label><label>Terapis<select bind:value={therapist}>{#each team as t}<option>{t.name}</option>{/each}</select></label><div class="form-row"><label>Tanggal<input required type="date" bind:value={date}/></label><label>Jam (WIB)<input required type="time" bind:value={time}/></label></div><div class="booking-total"><span>Harga contoh</span><strong>{money(services.find(s=>s.name===service).price)}</strong></div><button class="primary submit" type="submit">Simpan reservasi <ArrowUpRight size={18}/></button></form></div></div>{/if}

